// One message per due item. The database decided WHO and WHEN; this only words it.
const ROLE = { hiring_manager: 'the hiring manager', hr: 'HR', finance: 'finance', department_head: 'the department head' };
const days = (iso) => Math.max(0, Math.floor((Date.now() - Date.parse(iso)) / 864e5));
return $input.all().map(({ json: d }) => {
  const what = `${d.candidate} for ${d.title} (${d.requisition}, ${d.dept})`;
  const where = `step ${d.step} of ${d.steps}, ${ROLE[d.role] || d.role}`;
  let text;
  if (d.kind === 'notify') text = `Hiring approval waiting for you: ${what}. Your turn: ${where}. Open Hiring Approvals in the Werkbank.`;
  else if (d.kind === 'remind') text = `Reminder: the hiring approval for ${what} has waited ${days(d.since)} days for you (${where}).`;
  else if (d.kind === 'escalate') text = `Overdue: the hiring approval for ${what} has been open ${days(d.since)} days at ${where} (${d.approver}).`;
  else text = `Hiring approval ${d.status}: ${what}.` + (d.status === 'approved' ? ' The chain is complete.' : ' The request is closed; a changed request is a new request.');
  return { json: { id: d.id, kind: d.kind, to: d.to, text } };
});

// Run report: how many notices were recorded this run (created = false means someone had already recorded it).
const rows = $input.all().map(({ json }) => json);
return [{ json: { recorded: rows.filter((r) => r.created === true).length, alreadyRecorded: rows.filter((r) => r.created === false).length } }];

// A message that could not be sent is NOT recorded, so the next run tries again. This only lists them.
const failed = $input.all().map(({ json }) => ({ id: $('Write the message').item.json.id, kind: $('Write the message').item.json.kind, error: json.error?.message || 'send failed' }));
return [{ json: { failed: failed.length, items: failed } }];
